    SELECT 'bosques-endemicos-de-9560', '9560', 'Bosques endémicos de Juniperus spp.', 'Bosque', 'Bosques abiertos y luminosos de sabinas y enebros arbóreos (Juniperus), con los árboles separados entre sí y un pasto o matorral bajo entre ellos. Se instalan donde el frío, el viento o la falta de suelo impiden que se cierre un bosque, desde páramos continentales hasta laderas costeras. Crecen extraordinariamente despacio y son muy longevos, así que un sabinar arrasado no vuelve en una vida humana.', 1, 37.579919, -1.340745, '#9acd32', '{"type":"Polygon","coordinates":[[[-1.382156,37.581331],[-1.382137,37.581259],[-1.382041,37.580805],[-1.381988,37.580588],[-1.381954,37.580433],[-1.381828,37.580408],[-1.381744,37.580391],[-1.381052,37.580264],[-1.380015,37.580097],[-1.379814,37.580227],[-1.379396,37.580262],[-1.378791,37.580078],[-1.377971,37.579789],[-1.377265,37.579662],[-1.376545,37.579605],[-1.375969,37.579719],[-1.375651,37.57973],[-1.375464,37.579674],[-1.375327,37.579498],[-1.374874,37.579249],[-1.37427,37.579168],[-1.373736,37.579235],[-1.373131,37.579556],[-1.372542,37.579647],[-1.372166,37.579705],[-1.371503,37.579623],[-1.371298,37.579535],[-1.37051,37.5792],[-1.369459,37.578854],[-1.369339,37.578841],[-1.367227,37.578623],[-1.365891,37.578419],[-1.365556,37.578367],[-1.363569,37.578182],[-1.363514,37.578175],[-1.363497,37.578255],[-1.36343,37.578331],[-1.363388,37.578378],[-1.363222,37.57845],[-1.363048,37.578456],[-1.361763,37.578303],[-1.361394,37.578258],[-1.360547,37.578151],[-1.35882,37.577807],[-1.358003,37.577753],[-1.357071,37.57774],[-1.3561,37.57774],[-1.35462,37.577524],[-1.353669,37.577319],[-1.352845,37.577244],[-1.352064,37.577285],[-1.351963,37.577297],[-1.35179,37.57729],[-1.351624,37.577216],[-1.351515,37.577095],[-1.351499,37.577016],[-1.350853,37.57709],[-1.349513,37.577157],[-1.348548,37.57702],[-1.348205,37.576934],[-1.346922,37.576616],[-1.346638,37.576531],[-1.346044,37.576352],[-1.345655,37.576109],[-1.344965,37.575374],[-1.34472,37.