    SELECT 'matorrales-arborescentes-de-5220', '5220', 'Matorrales arborescentes de Ziziphus', 'Matorral', 'Espinares de azufaifo (Ziziphus lotus), matas hemisféricas de ramas entrelazadas y espinas ganchudas que forman islas de sombra sobre llanos áridos. Cada mata levanta un pequeño montículo de arena y hojarasca y guarda debajo humedad, semillas y fauna que fuera no sobreviviría. Es el único hábitat de clima casi desértico de Europa occidental, y por eso figura como prioritario.', 1, 37.570681, -1.343956, '#cd853f', '{"type":"MultiPolygon","coordinates":[[[[-1.383474,37.571172],[-1.383469,37.570953],[-1.383382,37.570835],[-1.383356,37.570745],[-1.383298,37.570807],[-1.383125,37.571197],[-1.383038,37.571599],[-1.382764,37.572068],[-1.382332,37.572296],[-1.381798,37.572377],[-1.381021,37.57226],[-1.380358,37.572053],[-1.379898,37.571734],[-1.379668,37.571435],[-1.37951,37.570942],[-1.379367,37.570586],[-1.379122,37.570355],[-1.378993,37.570333],[-1.37856,37.570539],[-1.37833,37.570642],[-1.37807,37.570733],[-1.377667,37.570802],[-1.377451,37.570688],[-1.377279,37.570537],[-1.376962,37.570148],[-1.37679,37.569873],[-1.376545,37.569725],[-1.376257,37.569701],[-1.375811,37.569895],[-1.375464,37.570388],[-1.37519,37.570788],[-1.374671,37.571087],[-1.374354,37.571144],[-1.374196,37.57104],[-1.374196,37.570846],[-1.374254,37.57041],[-1.374557,37.569894],[-1.374861,37.56954],[-1.374846,37.569242],[-1.374674,37.56901],[-1.374286,37.568748],[-1.373292,37.568689],[-1.372644,37.568723],[-1.372183,37.568791],[-1.371779,37.569064],[-1.371649,37.569306],[-1.371548,37.569764],[-1.371532,37.570075],[-1.371402,37.570418],[-1.371128,37.570682],[-1.370739,37.570945],[-1.370177,37.571036],[-1.369472,37.570885],[-1.369097,37.570483],[-1.369055,37.570437],[-1.368782,37.570141],[-1.368738,37.570086],[-1.368422,37.569703],[-1.36812,37.569269],[-1.367805,37.568856],[-1.36769,37.568409],[-1.367489,37.568167],[-1.367144,37.568007],[-1.366524,37.568052],[-1.366077,37.568166],[-1.365631,37.568