    SELECT 'prados-calcareos-carsticos-6110', '6110', 'Prados calcáreos cársticos o basófilos del Alysso-Sedion albi', 'Pastos', 'Pastos abiertos sobre repisas y lanchas de roca caliza con apenas un dedo de tierra encima. Ahí solo prosperan plantas crasas de hojas gordas, como las uñas de gato (Sedum), y hierbas anuales minúsculas que nacen, florecen y mueren entre febrero y mayo. Ocupa superficies muy pequeñas y depende de que el suelo siga siendo escaso: en cuanto se acumula tierra, otras plantas lo desplazan.', 1, 37.572798, -1.34154, '#9acd32', '{"type":"MultiPolygon","coordinates":[[[[-1.363528,37.578107],[-1.363475,37.577962],[-1.363347,37.577852],[-1.363172,37.577798],[-1.36189,37.577645],[-1.360715,37.577496],[-1.358958,37.577147],[-1.358046,37.577087],[-1.357078,37.577073],[-1.356177,37.577072],[-1.354805,37.576873],[-1.353827,37.576663],[-1.352865,37.576575],[-1.351975,37.576622],[-1.351841,37.576638],[-1.351667,37.576694],[-1.351538,37.576802],[-1.351484,37.576948],[-1.351499,37.577016],[-1.351515,37.577095],[-1.351624,37.577216],[-1.35179,37.57729],[-1.351963,37.577297],[-1.352064,37.577285],[-1.352845,37.577244],[-1.353669,37.577319],[-1.35462,37.577524],[-1.3561,37.57774],[-1.357071,37.57774],[-1.358003,37.577753],[-1.35882,37.577807],[-1.360547,37.578151],[-1.361394,37.578258],[-1.361763,37.578303],[-1.363048,37.578456],[-1.363222,37.57845],[-1.363388,37.578378],[-1.36343,37.578331],[-1.363497,37.578255],[-1.363514,37.578175],[-1.363528,37.578107]]],[[[-1.344133,37.573438],[-1.344076,37.573093],[-1.343803,37.572726],[-1.343415,37.572439],[-1.342912,37.572024],[-1.342825,37.571796],[-1.342841,37.571429],[-1.343014,37.570904],[-1.343174,37.57041],[-1.343203,37.57017],[-1.342801,37.569812],[-1.342354,37.569572],[-1.341764,37.569618],[-1.341317,37.569812],[-1.340942,37.570145],[-1.340624,37.570568],[-1.340335,37.571082],[-1.34019,37.57145],[-1.340117,37.571999],[-1.340116,37.572296],[-1.340116,37.5724],[-1.34,37.572905],[-1.339755,37.573327],[-1.339307,37