    SELECT 'pendientes-rocosas-calcicolas-8210', '8210', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Roquedos', 'Paredes y cortados de roca caliza en los que la vegetación no vive sobre el suelo, sino dentro de las fisuras. Son plantas de raíz larguísima y crecimiento lentísimo, agarradas a la grieta, que aprovechan el agua que escurre por la pared. Los roquedos han quedado a salvo del arado y del ganado durante milenios, y por eso concentran una proporción altísima de especies que no existen en ningún otro lugar.', 0, 37.565542, -1.33655, '#daa520', '{"type":"MultiPolygon","coordinates":[[[[-1.363528,37.578107],[-1.363475,37.577962],[-1.363347,37.577852],[-1.363172,37.577798],[-1.36189,37.577645],[-1.360715,37.577496],[-1.358958,37.577147],[-1.358046,37.577087],[-1.357078,37.577073],[-1.356177,37.577072],[-1.354805,37.576873],[-1.353827,37.576663],[-1.352865,37.576575],[-1.351975,37.576622],[-1.351841,37.576638],[-1.351667,37.576694],[-1.351538,37.576802],[-1.351484,37.576948],[-1.351499,37.577016],[-1.351515,37.577095],[-1.351624,37.577216],[-1.35179,37.57729],[-1.351963,37.577297],[-1.352064,37.577285],[-1.352845,37.577244],[-1.353669,37.577319],[-1.35462,37.577524],[-1.3561,37.57774],[-1.357071,37.57774],[-1.358003,37.577753],[-1.35882,37.577807],[-1.360547,37.578151],[-1.361394,37.578258],[-1.361763,37.578303],[-1.363048,37.578456],[-1.363222,37.57845],[-1.363388,37.578378],[-1.36343,37.578331],[-1.363497,37.578255],[-1.363514,37.578175],[-1.363528,37.578107]]],[[[-1.347314,37.565408],[-1.346577,37.56508],[-1.346276,37.564907],[-1.346175,37.564666],[-1.346206,37.564367],[-1.346237,37.564068],[-1.346036,37.563907],[-1.345547,37.563792],[-1.3451,37.563698],[-1.34487,37.563641],[-1.344697,37.563537],[-1.344555,37.563193],[-1.344355,37.562802],[-1.343996,37.562536],[-1.343263,37.562372],[-1.342758,37.562338],[-1.342182,37.562233],[-1.341722,37.562058],[-1.341235,37.561553],[-1.34095,37.561001],[-1.340722,37.56053],[-1.340666,37.560094],[-1.340725,3