    SELECT 'matorrales-halonitrofilos-pegano-1430', '1430', 'Matorrales halonitrófilos (Pegano-Salsoletea)', 'Matorral', 'Matorral de suelos salinos removidos y cargados de nitrógeno: bordes de camino y de cultivo, márgenes de rambla, corrales y escombreras viejas. Lo forman matas robustas de hoja gris o carnosa —orgazas, sosas, bojas y cambroneras— que rebrotan enseguida tras cualquier alteración. Aunque nace de terrenos trastocados, es vegetación propia de los ambientes áridos del sureste y a menudo el último refugio de plantas escasas.', 0, 37.559387, -1.332302, '#9acd32', '{"type":"MultiPolygon","coordinates":[[[[-1.343943,37.55565],[-1.34392,37.555648],[-1.343888,37.555605],[-1.343911,37.555482],[-1.343845,37.555367],[-1.343746,37.555379],[-1.343743,37.555396],[-1.343696,37.555532],[-1.343566,37.555696],[-1.343506,37.555771],[-1.343472,37.555798],[-1.343472,37.555824],[-1.343435,37.555824],[-1.343407,37.555823],[-1.343385,37.555804],[-1.343305,37.555804],[-1.34329,37.555817],[-1.343288,37.555844],[-1.343333,37.55586],[-1.343333,37.555889],[-1.343291,37.555918],[-1.343216,37.555923],[-1.343174,37.555914],[-1.34315,37.555909],[-1.343126,37.555934],[-1.343124,37.555955],[-1.343122,37.555976],[-1.343068,37.555987],[-1.343009,37.555985],[-1.342973,37.556001],[-1.342909,37.556002],[-1.34287,37.555994],[-1.34283,37.555986],[-1.342791,37.555992],[-1.342761,37.555996],[-1.342723,37.555963],[-1.342676,37.555957],[-1.342635,37.555968],[-1.34261,37.555991],[-1.342596,37.556017],[-1.342577,37.55603],[-1.342563,37.556065],[-1.342526,37.556055],[-1.342493,37.556055],[-1.34246,37.556063],[-1.342433,37.556064],[-1.342387,37.556065],[-1.34236,37.556053],[-1.342328,37.556065],[-1.342315,37.55607],[-1.342288,37.556062],[-1.342276,37.556041],[-1.342265,37.556037],[-1.342245,37.556048],[-1.342247,37.556049],[-1.342235,37.55606],[-1.342214,37.556065],[-1.342205,37.556069],[-1.342213,37.556078],[-1.342221,37.556086],[-1.3422,37.556099],[-1.342188,37.556105],[-1.342193,37.556122],[-1.3