-- 3. Especies (64). `identification_tips` va como texto separado por «; », que es como lo parte park_payload.php.
-- ------------------------------------------------------------------------------------------------
INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status, description, description_source, identification_tips, seasonality, image_url, image_attribution, latitude, longitude, rarity_score, rarity_basis, rarity_local, rarity_local_basis, is_featured, is_visible, hidden_reason, source, taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, spain_status, murcia_status, review_note, eidos_taxonid, gbif_species_key, zepa_site_code, is_migratory, site_presence)
SELECT pk.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status, s.description, s.description_source, s.identification_tips, s.seasonality, s.image_url, s.image_attribution, s.latitude, s.longitude, s.rarity_score, s.rarity_basis, s.rarity_local, s.rarity_local_basis, s.is_featured, s.is_visible, s.hidden_reason, s.source, s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.spain_status, s.murcia_status, s.review_note, s.eidos_taxonid, s.gbif_species_key, s.zepa_site_code, s.is_migratory, s.site_presence
FROM parks pk JOIN (
    SELECT 'Siempreviva insigne' common_name, 'Limonium insigne' scientific_name, 'flora' kingdom, 'Hierba' family, 'Suelos margosos y yesosos salinos, en estepas y taludes áridos' primary_habitat, 'Interés especial' conservation_status, 'Una de las siemprevivas más vistosas: sus inflorescencias forman un ramillete denso de un lila rosado intenso que destaca sobre el gris de las margas. Es un endemismo del sureste ibérico, ligado a suelos salinos y yesosos, y muy usado en seco como flor ornamental.' description, NULL description_source, 'Floración densa y de lila rosado vivo, muy llamativa; Hojas en roseta basal, gruesas y de borde ondulado; Sobre margas y yesos claros, en terreno casi desnudo' identification_tips, 'Final de primavera y verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_insigne.jpg?width=1280' image_url, 'ANE (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, NULL rarity_basis, 3 rarity_local, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}' rarity_local_basis, 0 is_featured, 1 is_visible, NULL hidden_reason, 'GBIF: 7 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Plumbaginaceae' taxon_family, 'Limonium' taxon_genus, 'NE (no evaluada a nivel global; género con numerosos microendemismos ibéricos)' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)' murcia_status, NULL review_note, 5836 eidos_taxonid, 4088635 gbif_species_key, NULL zepa_site_code, NULL is_migratory, NULL site_presence
    UNION ALL
    SELECT 'Zamarrilla lanuda', 'Teucrium lanigerum', 'flora', 'Mata aromática', 'Matorral y cerros sobre suelos calizos y margosos secos', 'Interés especial', 'Mata cubierta por una lana blanca y espesa que la hace destacar en el matorral. Sus flores, rosadas o purpúreas, se agrupan en cabezuelas terminales y carecen de labio superior, con los estambres al descubierto. Es un endemismo del sureste ibérico.', NULL, 'Toda la planta cubierta de lana blanca y espesa; Flores sin labio superior, con los estambres asomando; Cabezuelas apretadas en el extremo de las ramas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Teucrium_lanigerum_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 7 ocurrencias dentro de los polígonos de hábitat del espacio (8 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Teucrium', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 8809, 7308375, NULL, NULL, NULL
    UNION ALL
    SELECT 'Palmito', 'Chamaerops humilis', 'flora', 'Palmera', 'Matorral cálido, laderas soleadas y acantilados del piso termomediterráneo', 'Interés especial', 'La única palmera silvestre de Europa continental. Suele crecer en mata, con varios troncos cortos, aunque con los años puede levantar un tronco único. Sus hojas son abanicos rígidos con pecíolos muy espinosos. Del cogollo se sacaba el «palmito», y de las hojas, cordelería y escobas.', NULL, 'Hojas en abanico, rígidas y divididas en segmentos; Pecíolos con espinas fuertes en los bordes; Porte en mata, con varios troncos desde la base', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chamaerops_humilis_Torreblanca.jpg?width=1280', 'Canaan (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 5 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Liliopsida', 'Arecales', 'Arecaceae', 'Chamaerops', 'LC (Preocupación menor)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 3518, 2736625, NULL, NULL, NULL
    UNION ALL
    SELECT 'Albardín', 'Lygeum spartum', 'flora', 'Gramínea', 'Estepas salinas, margas y suelos yesosos secos; forma albardinales', 'LC', 'Gramínea perenne de hojas duras y punzantes que forma matas separadas sobre suelos salinos y margosos donde poco más prospera. Su inflorescencia es inconfundible: una espata blanca y sedosa que envuelve las flores como un capuchón de papel.', NULL, 'Espata blanca y sedosa envolviendo la espiga; Hojas rígidas terminadas en punta punzante; Matas espaciadas sobre suelo desnudo y claro', 'Todo el año (espigado en primavera)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lygeum_spartum-1.jpg?width=1280', 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 5 ocurrencias dentro de los polígonos de hábitat del espacio (7 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Lygeum', 'LC', 'No catalogada en la Lista Roja de la Flora Vascular Española 2008', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10060, 2704651, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lagartija colirroja', 'Acanthodactylus erythrurus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Protegida (LESRPE)', 'Lagartija de suelos arenosos, de cuerpo aplanado y dedos con escamas laterales en forma de peine que le sirven de raqueta sobre la arena suelta. Los jóvenes tienen la cola y las patas traseras de un rojo intenso que se apaga en los adultos.', NULL, 'Dedos con flecos de escamas a los lados, como peines; Jóvenes con cola y patas traseras rojo intenso; Cuerpo aplanado, con rayas y ocelos claros en el dorso', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Benny_Trapp_Acanthodactylus_erythrurus.jpg?width=1280', 'Benny Trapp (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Acanthodactylus', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11220, 5226733, NULL, NULL, NULL
    UNION ALL
    SELECT 'Oroval', 'Withania frutescens', 'flora', 'Arbusto', 'Matorral cálido, roquedos y ramblas de clima muy seco', 'No catalogada', 'Arbusto de la familia del tomate y la belladona, con hojas ovaladas algo carnosas y flores verdosas discretas. Los frutos son bayas rojas y brillantes envueltas en el cáliz. Es una especie de raíz norteafricana que en la península solo vive en los rincones más cálidos del sureste.', NULL, 'Bayas rojas pequeñas asomando del cáliz; Hojas ovales, algo carnosas y de verde apagado; Flores verde amarillentas, poco vistosas', 'Primavera y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Withania_frutescens0176.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Solanales', 'Solanaceae', 'Withania', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE; elemento iberoafricano de interés biogeográfico', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 9438, 3801152, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lechuguilla lanosa', 'Launaea lanifera', 'flora', 'Hierba', 'Matorral árido y bordes de rambla', 'Interés especial', 'Compuesta de aspecto blanquecino por la lana que cubre tallos y hojas, con una roseta basal y capítulos amarillos tipo diente de león. Suelta látex blanco al romperse. Es una planta iberoafricana ligada a los ambientes más áridos.', NULL, 'Lana blanca cubriendo tallos y base de las hojas; Capítulos amarillos tipo diente de león; Látex blanco al partir un tallo', 'Primavera-verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/627205605/original.jpg', 'Olivier Argagnon (CC BY 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Launaea', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 473, 3144842, NULL, NULL, NULL
    UNION ALL
    SELECT 'Saladilla anual', 'Limonium lobatum', 'flora', 'Hierba', 'Saladares, arenas litorales y suelos salinos secos', 'No catalogada', 'Saladilla anual —a diferencia de la mayoría de sus parientes, que son perennes— con una roseta de hojas lobuladas pegada al suelo y tallos alados que rematan en espigas de flores azuladas o violáceas. Sus flores conservan el color al secarse, un truco común en el género.', NULL, 'Roseta basal de hojas con lóbulos redondeados; Tallos con alas o costillas, no cilíndricos; Flores azuladas agrupadas en espiguillas de un solo lado', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_lobatum.jpg?width=1280', 'Sf2000 (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Plumbaginaceae', 'Limonium', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 5839, 8419208, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cambrón', 'Lycium intricatum', 'flora', 'Arbusto', 'Matorral costero y suelos salinos y nitrificados de clima cálido', 'Interés especial', 'Arbusto de ramas enmarañadas y espinosas, con hojitas carnosas agrupadas en manojos. Sus flores son pequeñas, tubulares y de color violeta pálido, y da bayas rojas que comen muchas aves. Forma setos impenetrables que dan refugio a pájaros y reptiles.', NULL, 'Ramas enredadas entre sí y terminadas en espina; Hojas carnosas en manojitos a lo largo de la rama; Bayas rojas pequeñas y flores tubulares violáceas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lycium_intrincatum_(flor).JPG?width=1280', 'ANE (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Solanales', 'Solanaceae', 'Lycium', 'NE (no evaluada a nivel global)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 5923, 3796884, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cornical', 'Periploca angustifolia', 'flora', 'Arbusto', 'Matorral cálido, laderas soleadas y barrancos de clima muy seco', 'Vulnerable', 'Arbusto de hojas estrechas y coriáceas y flores pequeñas con cinco pétalos de un pardo verdoso y aspecto aterciopelado. Sus frutos son dos vainas largas y curvas dispuestas en forma de cuerno, de donde le viene el nombre popular de cornical. Suelta látex al romperse.', NULL, 'Frutos en dos vainas curvas enfrentadas, como cuernos; Látex blanco al partir una hoja o rama; Flores pardo verdosas con aspecto de terciopelo', 'Primavera y verano (floración)', 'https://inaturalist-open-data.s3.amazonaws.com/photos/609975159/original.jpg', 'Quentin Groom (CC0) · GBIF', NULL, NULL, 3, NULL, 4, '{"categoria":"Vulnerable","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 1, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Gentianales', 'Apocynaceae', 'Periploca', 'NE (no evaluada a nivel global)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 7034, 6022574, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lagartija colilarga', 'Psammodromus algirus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Protegida (LESRPE)', 'Lagartija esbelta de escamas grandes, quilladas y brillantes, con dos líneas claras muy marcadas a cada lado del dorso. La cola puede medir el doble que el cuerpo. Los machos lucen en primavera manchas azules en el hombro y las mejillas anaranjadas.', NULL, 'Dos líneas claras nítidas a lo largo de cada costado; Escamas grandes y quilladas, de aspecto brillante; Cola larguísima, hasta el doble que el cuerpo', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Psammodromus_algirus_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Psammodromus', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10670, 2469763, NULL, NULL, NULL
    UNION ALL
    SELECT 'Salsola', 'Salsola papillosa', 'flora', 'Mata', 'Estepas salinas y suelos margosos y yesosos con sal', 'Vulnerable', 'Mata baja y densa de hojas cortas y carnosas cubiertas de pequeñas papilas que le dan un tacto áspero. Es un endemismo ibérico ligado a suelos salinos y margosos, con una distribución muy fragmentada, lo que la hace especialmente sensible a la roturación.', NULL, 'Superficie de las hojas rugosa, con papilas visibles de cerca; Mata compacta y grisácea, de porte bajo; Frutos con alas membranosas al madurar', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Salsola_papillosa1160031.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 5, NULL, 4, '{"categoria":"Vulnerable","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 1, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Salsola', 'LC (Preocupación menor)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 7915, 3757043, NULL, NULL, NULL
    UNION ALL
