    SELECT 'Boja negra', 'Artemisia barrelieri', 'flora', 'Mata aromática', 'Matorrales halo-nitrófilos', 'NE', 'Mata aromática grisácea de las bojas del sureste árido, colonizadora de suelos alterados, bordes de camino y matorrales nitrificados.', NULL, 'Olor aromático fuerte al frotar; Follaje gris-plateado; Indica suelos alterados', 'Otoño', 'https://inaturalist-open-data.s3.amazonaws.com/photos/173279674/original.jpeg', 'Yamil J.R (CC0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Artemisia', 'NE', 'No incluida en el LESRPE; característica de matorrales halonitrófilos (HIC 1430)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 9913, 3120786, NULL, NULL, NULL
    UNION ALL
    SELECT 'Orgaza', 'Atriplex glauca', 'flora', 'Mata', 'Matorrales halo-nitrófilos', 'LC', 'Mata baja y extendida, de hojas pequeñas, grisáceas y cubiertas de escamas harinosas que reflejan la luz. Marca los suelos con sal y exceso de nitrógeno, como los antiguos apriscos. Sus frutos van encerrados entre dos valvas endurecidas.', NULL, 'Hojas pequeñas, grises y harinosas al tacto; Porte bajo y muy extendido, casi tendido; Frutos entre dos valvas duras y dentadas', 'Verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/611378691/original.jpg', 'Michael Bakker Paiva (CC BY 4.0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Atriplex', 'LC', 'No incluida en el LESRPE; característica de matorrales halonitrófilos (HIC 1430)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 2639, 7501008, NULL, NULL, NULL
    UNION ALL
    SELECT 'Orejilla de roca', 'Lafuentea rotundifolia', 'flora', 'Hierba', 'Roquedos y fisuras calcáreas costeras', 'Vulnerable', 'Planta rupícola de hojas redondeadas, dentadas y algo carnosas, que forma matas colgantes en las paredes calizas. Sus flores, blanquecinas con toques amarillos, se agrupan en racimos erguidos. Es un endemismo iberoafricano restringido al sureste peninsular y al norte de África.', NULL, 'Hojas redondas y dentadas, casi como monedas; Racimos de flores blanquecinas erguidos sobre el follaje; Forma matas colgantes en pared caliza', 'Floración primaveral', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lafuentea_rotundifolia80857.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 4, NULL, 4, '{"categoria":"Vulnerable","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 1, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Plantaginaceae', 'Lafuentea', 'NE', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 5616, 3739515, NULL, NULL, NULL
