    SELECT 'Brochera pegajosa', 'Santolina viscosa', 'flora', 'Mata', 'Vive en tomillares sobre yesos, hasta 600 m', 'Interés especial', 'Planta de 15-45 cm, cubierta de glandulas sésiles, por lo que resulta pegajosa, con tallos densamente foliosos, hojas de 8-25 mm, con largo pecíolo, pinnatisectas con cinco hileras de segmentos, las superiores lineares. Capítulos numerosos, solitarios en cada escapo, de 5-10 mm de diámetro, subglobosos, con varias filas de brácteas. Florecillas todas tubulares, glandulosas, amarillas. Aquenios 1,2-1,5 mm, angulosos, sin vilano.', NULL, NULL, 'Marzo a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Santolina_viscosa_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Santolina', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 665, 4252495, NULL, NULL, NULL
    UNION ALL
    SELECT 'Senecio flavus', 'Senecio flavus', 'flora', 'Hierba', 'Ramblas, arenales y suelos removidos de clima árido', 'Vulnerable', 'Hierba anual de hojas carnosas y algo azuladas, con cabezuelas amarillas cuyas lígulas se enrollan hacia atrás al abrirse. Es una planta de estirpe sahariana que en Europa solo aparece en los rincones más áridos del sureste ibérico, tras las lluvias.', NULL, 'Lígulas amarillas enrolladas hacia atrás; Hojas carnosas y de verde azulado; Aparece en masa tras las lluvias y desaparece pronto', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Senecio_flavus_1.jpg?width=1280', 'Gideon Pisanty (Gidip) גדעון פיזנטי (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 4, NULL, 4, '{"categoria":"Vulnerable","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 1, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Senecio', 'NE', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 687, 3107479, NULL, NULL, NULL
    UNION ALL
    SELECT 'Espinacas', 'Suaeda spicata', 'flora', NULL, NULL, 'No catalogada', NULL, NULL, NULL, 'Marzo a noviembre', NULL, NULL, NULL, NULL, 3, NULL, 1, NULL, 0, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Suaeda', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 8516, 3756223, NULL, NULL, NULL
