    SELECT 'Salamanquesa común', 'Tarentola mauritanica', 'fauna', 'Reptil', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Protegida (LESRPE)', 'Gecko robusto de piel tuberculada, activo al anochecer sobre roquedos, muros y cortados, donde caza insectos atraídos por la luz.', NULL, 'Piel rugosa con tubérculos; Activa al atardecer; Trepa por rocas y muros', 'Todo el año', 'https://inaturalist-open-data.s3.amazonaws.com/photos/605672084/original.jpg', 'jrodben (CC BY-NC 4.0) · GBIF', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Phyllodactylidae', 'Tarentola', 'LC', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11692, 2445034, NULL, NULL, NULL
    UNION ALL
    SELECT 'Teucrio de Freyn', 'Teucrium freynii', 'flora', 'Mata aromática', 'Roquedos, pedregales y ramblas sobre suelos calizos secos', 'Interés especial', 'Teucrio endémico del sureste ibérico, de porte bajo y aspecto blanquecino, con hojas pequeñas y enrolladas y flores rosadas o blanquecinas sin labio superior. Como todas las labiadas, tiene el tallo de sección cuadrada y desprende aroma al frotarlo.', NULL, 'Flores sin labio superior, con los estambres asomando; Tallo de sección cuadrada, típico de labiada; Hojas pequeñas y enrolladas, de aspecto grisáceo', 'Primavera-verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Teucrium_freynii_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Teucrium', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 8800, 3896744, NULL, NULL, NULL
