    SELECT 'Murciélago de cueva', 'Miniopterus schreibersii', 'fauna', 'Murciélago', 'Cuevas y minas; caza en vuelo alto sobre bosque, campo y láminas de agua', 'Vulnerable', 'Murciélago de alas largas y estrechas y vuelo rápido y alto, casi como el de un vencejo. Tiene la frente muy abombada y el pelo corto y erizado en la cabeza. Recorre decenas de kilómetros entre las cuevas de cría, de tránsito y de invernada.', NULL, 'Frente muy abombada y pelo corto y de punta; Alas largas y estrechas; vuelo veloz y alto; Forma colonias enormes y muy apretadas en cueva', 'Todo el año, con desplazamientos estacionales entre cuevas', 'https://commons.wikimedia.org/wiki/Special:FilePath/Miniopterus_schreibersii_dasythrix.jpg?width=1280', 'Andrew Smith (Public domain) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 1, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Formulario Normalizado de Datos del sitio Red Natura 2000 ES6200011 (Sierra de las Moreras), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Mammalia', 'Chiroptera', 'Miniopteridae', 'Miniopterus', 'VU (Vulnerable) (evaluación UICN 2023)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12169, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago ratonero mediano', 'Myotis blythii', 'fauna', 'Murciélago', 'Cuevas y desvanes; caza saltamontes en pastizales y herbazales', 'Interés especial', 'Casi idéntico al ratonero grande, con el que a menudo comparte colonia, pero algo menor y con el hocico más estrecho y una mancha clara en la frente. Está especializado en cazar saltamontes en pastizales altos, lo que reparte el alimento entre ambas especies.', NULL, 'Muy parecido al ratonero grande, pero algo menor; Mancha clara difusa entre los ojos; Hocico más fino y estrecho', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Myotis-blythii-cropped.jpg?width=1280', 'C. Robiller / www.naturlichter.de (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 1, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Formulario Normalizado de Datos del sitio Red Natura 2000 ES6200011 (Sierra de las Moreras), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Mammalia', 'Chiroptera', 'Vespertilionidae', 'Myotis', 'LC (Preocupación menor) (evaluación UICN 2016)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 10866, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago ratonero grande', 'Myotis myotis', 'fauna', 'Murciélago', 'Cuevas y desvanes; caza escarabajos en pastos, claros y bosque sin sotobosque', 'Interés especial', 'Uno de los murciélagos más grandes de Europa, con orejas largas y anchas y hocico de aspecto perruno. Caza cerca del suelo, capturando escarabajos que localiza por el ruido que hacen al andar, no solo con el sonar. Cría en colonias numerosas en cuevas y bajo cubiertas.', NULL, 'Talla grande y orejas largas y anchas; Hocico ancho, de aspecto casi perruno; Caza a ras de suelo, en zonas despejadas', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Myotis.jpg?width=1280', 'Urheber: Manuel Werner, Germany, Wikipedia-Kontakt: http://de.wikip… (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 1, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Formulario Normalizado de Datos del sitio Red Natura 2000 ES6200011 (Sierra de las Moreras), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Mammalia', 'Chiroptera', 'Vespertilionidae', 'Myotis', 'LC (Preocupación menor) (evaluación UICN 2016)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 11803, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago grande de herradura', 'Rhinolophus ferrumequinum', 'fauna', 'Murciélago', 'Cuevas, minas y desvanes para refugiarse; caza en mosaicos de bosque y pasto', 'Interés especial', 'El mayor de los murciélagos de herradura ibéricos. Debe el nombre a la hoja nasal en forma de herradura con la que emite el sonar por la nariz, no por la boca. Al reposar se envuelve por completo en las alas, como en una capa, y cuelga libre del techo.', NULL, 'Al dormir se envuelve entero en las alas; Hoja nasal en forma de herradura alrededor de las fosas; Cuelga separado del techo, no metido en una grieta', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Grand_Rhinolophe_2.jpg?width=1280', 'Marie Jullion (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 1, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Formulario Normalizado de Datos del sitio Red Natura 2000 ES6200011 (Sierra de las Moreras), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Mammalia', 'Chiroptera', 'Rhinolophidae', 'Rhinolophus', 'LC (Preocupación menor) (evaluación UICN 2016)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 11264, 2432655, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago pequeño de herradura', 'Rhinolophus hipposideros', 'fauna', 'Murciélago', 'Cuevas, minas y edificios; caza en bosque, sotos y setos', 'Interés especial', 'El más pequeño de los murciélagos de herradura europeos: colgado y envuelto en sus alas no llega al tamaño de una ciruela. Vuela bajo y muy cerca de la vegetación, con revoloteo de mariposa. Es muy sensible a las molestias en sus refugios de cría e invernada.', NULL, 'Tamaño minúsculo, como una ciruela colgando; Vuelo bajo y revoloteante junto a setos y muros; Se envuelve en las alas al reposar, como sus parientes', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kleine_Hufeisennase.jpg?width=1280', 'F. C. Robiller / naturlichter.de (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Formulario Normalizado de Datos del sitio Red Natura 2000 ES6200011 (Sierra de las Moreras), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Mammalia', 'Chiroptera', 'Rhinolophidae', 'Rhinolophus', 'LC (Preocupación menor) (evaluación UICN 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 11451, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gusanera', 'Sideritis lasiantha', 'flora', NULL, NULL, 'Vulnerable', NULL, NULL, NULL, 'Marzo, abril, mayo, junio, julio, agosto, septiembre, octubre, diciembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sideritis_lasiantha32.jpg?width=1280', 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, NULL, 4, '{"categoria":"Vulnerable","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 1, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.3, que la cita como «Sideritis lasiantha Pers.»: escasa; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Sideritis', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 8338, NULL, NULL, NULL, NULL
