    SELECT 'Tortuga mora', 'Testudo graeca', 'fauna', 'Reptil', 'Matorral termomediterráneo semiárido', 'Vulnerable', 'Tortuga terrestre de caparazón abombado con dibujo de placas amarillas y negras, la única silvestre del sureste peninsular. Se reconoce por un tubérculo córneo a cada lado de la cola —el «espolón»— y por no tener el peto articulado. Pasa el verano y el invierno inactiva, refugiada bajo matas y madrigueras.', NULL, 'Un tubérculo córneo a cada lado de la base de la cola; Caparazón abombado con placas amarillas y negras; Peto sin bisagra: no puede cerrarse del todo', 'Primavera y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Nabeulensis_sarda.JPG?width=1280', 'Gisella D. (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Catálogo Español de Especies Amenazadas / LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 1, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.3: presente; Formulario Normalizado de Datos del sitio Red Natura 2000 ES6200011 (Sierra de las Moreras), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Testudines', 'Testudinidae', 'Testudo', 'VU A1cd (evaluación IUCN de 1996; pendiente de reevaluación global reciente)', 'Catálogo Español de Especies Amenazadas / LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Hábitats 92/43/CEE, Anexos II y IV; Reglamento CITES (CE) 338/97, Anexo A', 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 11385, 2441461, NULL, NULL, NULL
    UNION ALL
    SELECT 'Collalba negra', 'Oenanthe leucura', 'fauna', 'Ave', 'Matorral litoral, laderas secas y roquedos', 'Protegida (LESRPE)', 'La mayor de las collalbas, enteramente negra salvo el obispillo y la base de la cola, blancos. Vive en cortados y laderas rocosas, donde construye junto al nido una plataforma de piedrecitas que acarrea una a una. Su canto es potente y melodioso.', NULL, 'Cuerpo negro con obispillo blanco muy contrastado; «T» negra invertida en la cola blanca al volar; Montoncitos de piedrecitas junto a la grieta del nido', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Black_Wheatear%2C_Isla_Plana_3.jpg?width=1280', 'Andrew Thomas from Shrewsbury, UK (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 44 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Oenanthe', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11592, 5231236, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Cogujada montesina', 'Galerida theklae', 'fauna', 'Ave', 'Matorral bajo, laderas pedregosas y eriales con vegetación rala', 'Protegida (LESRPE)', 'Cogujada de cresta puntiaguda, muy parecida a la común pero de pico más corto y grueso y con el pecho más nítidamente rayado. Prefiere el matorral y las laderas pedregosas, mientras que la común busca cultivos, caminos y bordes de pueblo.', NULL, 'Cresta alta y afilada, casi triangular; Pico más corto y romo que el de la cogujada común; Rayado del pecho bien definido, no difuminado', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Galerida_theklae_Madrid.jpg?width=1280', 'Adrian198cm (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 36 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Galerida', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12316, 9330514, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Cogujada común', 'Galerida cristata', 'fauna', 'Ave', 'Cultivos, caminos, eriales y bordes de poblado con suelo desnudo', 'Protegida (LESRPE)', 'Alondra parda de cresta alta y puntiaguda, muy ligada a caminos, cunetas y descampados junto a los pueblos. Camina en vez de saltar y, al volar, deja ver el forro rojizo de las alas y la cola con los bordes canela.', NULL, 'Cresta larga y puntiaguda, casi siempre erguida; Forro de las alas rojizo, visible al levantar el vuelo; Camina por el suelo en vez de saltar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Crested_Lark_-_Qatar.jpg?width=1280', 'Ashraf Kotb (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 19 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Galerida', 'LC', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11102, 2490669, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
