    SELECT 'Águila real', 'Aquila chrysaetos', 'fauna', 'Ave rapaz', 'Montañas y sierras con cortados rocosos y amplias zonas abiertas de caza', 'Interés especial', 'La mayor de las águilas ibéricas, con casi dos metros y medio de envergadura y una nuca dorada que le da nombre. Cría en repisas de cantiles y usa territorios enormes, que una pareja defiende durante años. Planea con las alas en una «V» muy suave y bate poco, lo que la distingue de las rapaces menores.', NULL, 'Nuca y cogote de tono dorado, visibles a buena luz; Planea con las alas en «V» muy abierta y bate poco; Tamaño enorme: dobla al ratonero en el mismo cielo', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Maakotka_(Aquila_chrysaetos)_by_Jarkko_J%C3%A4rvinen.jpg?width=1280', 'Jarkko Järvinen (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF confirma su presencia con 18 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Aquila', 'LC (Preocupación menor)', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE; Ley 42/2007, Anexo IV', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 10888, 2480506, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Curruca rabilarga', 'Curruca undata', 'fauna', 'Ave', 'Matorral bajo y denso, jarales, brezales y tomillares', 'LC', 'Curruca pequeña, oscura y de cola muy larga que suele llevar levantada. El macho tiene el vientre vinoso y el ojo rojo rodeado de un anillo del mismo color. Es muy inquieta y rara vez se deja ver más de unos segundos antes de volver a hundirse en la mata.', NULL, 'Cola larga y erguida, casi vertical al posarse; Ojo y anillo ocular rojos; Vientre de color vinoso, con motitas blancas en la garganta', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fauvette_pitchou_Ichkeul_NP.jpg?width=1280', 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 1, NULL, 'GBIF confirma su presencia con 17 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2, que la cita como «Sylvia undata»: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 80931, 2492949, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Cernícalo vulgar', 'Falco tinnunculus', 'fauna', 'Ave rapaz', 'Campos abiertos, matorral, cortados y también ciudades', 'Protegida (LESRPE)', 'El halcón más común y fácil de ver, gracias a su costumbre de cernirse: se queda suspendido en el aire batiendo las alas con la cabeza inmóvil, buscando ratones y lagartijas. El macho tiene la cabeza gris y el dorso rojizo con puntos negros; la hembra es más parda y barrada.', NULL, 'Se queda «clavado» en el aire cerniéndose; Dorso rojizo salpicado de puntos negros; Cola larga con una banda negra ancha en la punta', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Common_kestrel_falco_tinnunculus.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 14 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente, común; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Falco', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12321, 9616058, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Tarabilla europea', 'Saxicola rubicola', 'fauna', 'Ave', 'Matorral bajo, herbazales, ribazos y bordes de cultivo con posaderos', 'Protegida (LESRPE)', 'Pájaro pequeño y regordete que se posa en lo alto de las matas, muy erguido y a la vista, para lanzarse al suelo a por insectos. El macho tiene la cabeza negra, un collar blanco a los lados y el pecho naranja. Su reclamo suena como dos piedras golpeadas, de donde le viene el nombre.', NULL, 'Siempre en lo alto de una mata, bien visible; Macho con capucha negra y medio collar blanco; Reclamo como el chasquido de dos cantos rodados', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Malestonechatseaham_Cropped.jpg?width=1280', 'derivative work: Myosotis Scorpioides (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 14 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2, que la cita como «Saxicola torquatus»: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Saxicola', 'LC (Preocupación menor)', 'Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 16387, 4408759, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Tórtola europea', 'Streptopelia turtur', 'fauna', 'Ave', 'Sotos, arboledas y matorral alto junto a cultivos y ramblas', 'VU', 'La más pequeña y grácil de nuestras palomas, con el dorso escamado en negro y canela y un parche a rayas blancas y negras en el cuello. Su arrullo ronco y adormecedor es uno de los sonidos del verano. Sus poblaciones han caído mucho en Europa por la pérdida de barbechos y setos.', NULL, 'Espalda escamada, como un mosaico canela y negro; Parche rayado blanco y negro a los lados del cuello; Arrullo ronco y vibrante, muy distinto al de la tórtola turca', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Streptopelia_turtur_Grlica0036.jpg?width=1280', 'Zrno at Serbian Wikipedia (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE, Anexo II (especie cinegética)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE, Anexo II (especie cinegética)","ambito":"estatal","origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 1, NULL, 'GBIF confirma su presencia con 9 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población reproductora, presente; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', NULL, NULL, 'Streptopelia', 'VU (Vulnerable)', 'No incluida en el LESRPE; Directiva Aves 2009/147/CE, Anexo II (especie cinegética); Reglamento CITES, Anexo A', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12356, 2495708, 'ES0000261', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Águila perdicera', 'Aquila fasciata', 'fauna', 'Ave rapaz', 'Sierras con cortados rocosos y amplias zonas abiertas de matorral y cultivo para cazar', 'En Peligro de Extinción', 'Águila mediana de alas largas y cola larga, con el vientre blanco finamente rayado y una mancha blanca en la espalda que se ve bien en vuelo. Caza a gran velocidad y a poca altura, sorprendiendo a perdices, conejos y palomas. Las parejas ocupan el mismo cortado durante años.', NULL, 'Mancha blanca en el centro de la espalda, visible desde arriba; Vientre claro y muy rayado, con una banda oscura en el borde del ala; Vuelo bajo y rápido cuando caza, no en círculos altos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aguila_perdicera.jpg?width=1280', 'Paco Gómez from Castellón, Spain (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"Catálogo Español de Especies Amenazadas: Vulnerable","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción","norma":"Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.","ambito":"Región de Murcia"}', 1, 1, NULL, 'GBIF confirma su presencia con 8 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Aquila', 'LC (población global amplia en Asia y África pese al declive europeo)', 'Catálogo Español de Especies Amenazadas: Vulnerable; Libro Rojo de las Aves de España (SEO/BirdLife, 2004/2021); Directiva Aves 2009/147/CE, Anexo I', 'En Peligro de Extinción (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 16302, 5844449, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Alcaraván', 'Burhinus oedicnemus', 'fauna', 'Ave esteparia', 'Llanos pedregosos, cultivos de secano, ramblas y eriales con poca cobertura', 'LC', 'Ave de aspecto extraño y ojos amarillos enormes, adaptados a la actividad nocturna. De día permanece agachada e inmóvil, confiada en su plumaje críptico, y solo al anochecer se activa y delata con un reclamo silbado y melancólico que recuerda al del zarapito.', NULL, 'Ojos amarillos desproporcionadamente grandes; Dos barras blancas y negras en el ala plegada; Reclamo silbado y triste al anochecer', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Burhinus_oedicnemus_insularum_Lanzarote_1.jpg?width=1280', 'Frank Vassen from Brussels, Belgium (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 1, NULL, 'GBIF confirma su presencia con 6 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Charadriiformes', 'Burhinidae', 'Burhinus', 'LC', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11887, 2482100, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Gaviota de Audouin', 'Larus audouinii', 'fauna', 'Ave marina', 'Islotes y costas mediterráneas; pesca en mar abierto cerca de la orilla', 'Vulnerable', 'Gaviota mediterránea de tamaño medio, elegante y de aspecto más «limpio» que la patiamarilla, con el pico rojo coral anillado de negro y las patas verdosas oscuras. Pesca al vuelo rozando el agua, sobre todo de noche y de madrugada. Cría en colonias muy concentradas en islotes y salinas.', NULL, 'Pico rojo coral con una banda negra cerca de la punta; Patas verde oscuro, no amarillas; Ojo oscuro que le da expresión suave', 'Todo el año, con concentraciones en verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/611415320/original.jpg', 'Michael Bakker Paiva (CC BY 4.0) · GBIF', NULL, NULL, 4, '{"categoria":"Catálogo Español de Especies Amenazadas (CEEA): Vulnerable","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 1, 1, NULL, 'GBIF confirma su presencia con 5 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población en concentración, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Larus', 'VU (Vulnerable)', 'Catálogo Español de Especies Amenazadas (CEEA): Vulnerable; Ley 42/2007, Anexo IV', 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 14053, 7406504, 'ES0000261', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Chova piquirroja', 'Pyrrhocorax pyrrhocorax', 'fauna', 'Ave', 'Cortados rocosos, cantiles y montañas, alimentándose en pastizales cercanos', 'LC', 'Córvido negro y brillante con el pico rojo, largo y curvo, y las patas del mismo color encendido. Vuela en grupos acrobáticos junto a los cantiles, plegando las alas y dejándose caer por puro juego. Busca larvas hurgando en el suelo de los pastos con ese pico de sonda.', NULL, 'Pico rojo, largo y curvado hacia abajo; Reclamo agudo, un «chiaa» nasal muy característico; Plumas de la punta del ala muy separadas, como dedos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pyrrhocorax_pyrrhocorax_-standing-8.jpg?width=1280', 'File:Alpenkrähe.jpg: "Malte Uhl (User:Zzzip)" derivative work: Snow… (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 1, NULL, 'GBIF confirma su presencia con 5 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', NULL, NULL, 'Pyrrhocorax', 'LC (Preocupación menor)', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE, Anexo I; Ley 42/2007, Anexo IV', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12065, 2482552, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Charrán patinegro', 'Thalasseus sandvicensis', 'fauna', 'Ave marina', 'Costas, bahías y salinas; pesca sobre aguas someras', 'Protegida (LESRPE)', 'Charrán grande y pálido, con un penacho negro despeinado en la nuca y un pico negro rematado en amarillo, como si lo hubiera mojado en mostaza. Pesca zambulléndose de golpe desde varios metros de altura. Fuera de la época de cría pierde el negro de la frente y queda con la coronilla blanca.', NULL, 'Punta amarilla en el pico negro; Nuca con plumas negras erizadas, en penacho; Se lanza al agua en picado, plegando las alas', 'Otoño e invierno principalmente', 'https://inaturalist-open-data.s3.amazonaws.com/photos/606127388/original.jpg', 'Diego González Dopico (CC BY 4.0) · GBIF', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 5 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población invernante, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Thalasseus', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12147, 2481240, 'ES0000261', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Cormorán moñudo', 'Gulosus aristotelis', 'fauna', 'Ave marina', 'Costas rocosas, acantilados e islotes; pesca buceando cerca de la orilla', 'LC', 'Cormorán marino de plumaje negro con reflejos verdosos, más esbelto que el grande y con la frente empinada. Bucea desde la superficie con un salto característico y persigue peces bajo el agua. Se seca con las alas abiertas sobre las rocas.', NULL, 'Salta hacia arriba antes de sumergirse; Frente muy empinada y pico fino; Se posa en roca con las alas abiertas al sol', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shag_Phalacrocorax_aristotelis.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"Subespecie mediterránea (desmarestii) catalogada Vulnerable en el Catálogo Español de Especies Amenazadas","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Subespecie mediterránea (desmarestii) catalogada Vulnerable en el Catálogo Español de Especies Amenazadas","ambito":"estatal","origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 1, 1, NULL, 'GBIF confirma su presencia con 4 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2, que la cita como «Phalacrocorax aristotelis aristotelis»: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Suliformes', 'Phalacrocoracidae', 'Gulosus', 'LC', 'Subespecie mediterránea (desmarestii) catalogada Vulnerable en el Catálogo Español de Especies Amenazadas', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 80933, 2481861, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Búho real', 'Bubo bubo', 'fauna', 'Ave rapaz nocturna', 'Cortados rocosos, barrancos y laderas con matorral y zonas abiertas de caza', 'Interés especial', 'El mayor búho de Europa, con casi dos metros de envergadura, penachos de plumas erguidos sobre la cabeza y ojos de un naranja encendido. Caza conejos, ratas e incluso otras rapaces. Su canto es un «bu-bo» profundo que se propaga kilómetros por los barrancos en las noches de invierno.', NULL, 'Penachos de plumas erguidos a los lados de la cabeza; Ojos naranjas muy intensos; Canto grave y profundo en las noches de invierno', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bubo_bubo_sibiricus_-_01.JPG?width=1280', 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF confirma su presencia con 3 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Strigiformes', 'Strigidae', 'Bubo', 'LC', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 10917, 5959092, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Camachuelo trompetero', 'Bucanetes githagineus', 'fauna', 'Ave esteparia', 'Ramblas, laderas peladas y llanos pedregosos de clima muy árido', 'LC', 'Pequeño fringílido de aspecto discreto y pardo arenoso, con un pico corto, muy grueso y de color rojo coral en primavera. El macho tiene además el pecho y el obispillo teñidos de rosa. Su reclamo es un zumbido nasal inconfundible, como una trompeta de juguete.', NULL, 'Pico corto y muy grueso, rojo coral en primavera; Reclamo nasal y zumbante, como una corneta pequeña; Tonos rosados en pecho y obispillo del macho', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bucanetes_githagineus_-Salinas_de_Janubio%2C_Lanzarote%2C_Spain-8.jpg?width=1280', 'Frank Vassen from Brussels, Belgium (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"Catalogado como Vulnerable en el Libro Rojo de las Aves de España (población ibérica escasa y localizada)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Catalogado como Vulnerable en el Libro Rojo de las Aves de España (población ibérica escasa y localizada)","ambito":"estatal","origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 1, 1, NULL, 'GBIF confirma su presencia con 3 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Fringillidae', 'Bucanetes', 'LC', 'Catalogado como Vulnerable en el Libro Rojo de las Aves de España (población ibérica escasa y localizada)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11363, 2494394, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Abubilla', 'Upupa epops', 'fauna', 'Ave', 'Campos abiertos, dehesas, cultivos con arbolado y bordes de matorral', 'Protegida (LESRPE)', 'Ave inconfundible de color canela con alas y cola a franjas blancas y negras, y una cresta eréctil que despliega en abanico al posarse. Sondea el suelo blando con el pico largo y curvo en busca de larvas e insectos. Su canto, un «up-up-up» sordo y repetido, se oye de lejos en primavera.', NULL, 'Vuelo ondulante y torpe, como una mariposa grande; Cresta que abre en abanico justo al aterrizar; Camina por el suelo clavando el pico largo y curvo', 'Todo el año en el sur peninsular; estival en el resto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Wiedehopf_mit_Puppe_als_Futter.jpg?width=1280', 'Sven Damerow (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 3 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Upupa', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11211, 2498415, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Garceta común', 'Egretta garzetta', 'fauna', 'Ave acuática', 'Marismas, salinas, ramblas con agua, arrozales y orillas costeras', 'Protegida (LESRPE)', 'Garza blanca y esbelta, de tamaño medio, con el pico negro y las patas negras rematadas en unos pies amarillos llamativos. Pesca removiendo el fondo con esas patas para levantar peces y camarones. En época de cría luce dos plumas largas y finas en la nuca.', NULL, 'Pies amarillos al final de patas negras; Pico negro y fino, no amarillo; Remueve el fondo con una pata mientras acecha', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aigrette_garzette_au_lac_sud_de_Tunis_(site_RAMSAR).jpg?width=1280', 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 2 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Egretta', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11340, 2480876, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Papamoscas gris', 'Muscicapa striata', 'fauna', 'Ave', 'Arbolado abierto, bordes de bosque, huertos y jardines con perchas altas', 'Protegida (LESRPE)', 'Pájaro discreto de color pardo grisáceo, sin marcas llamativas, que se reconoce mejor por su conducta que por su aspecto: se posa muy erguido en una rama descubierta, sale disparado a cazar un insecto en el aire y vuelve exactamente a la misma percha. Repite la maniobra decenas de veces.', NULL, 'Vuelve siempre a la misma rama tras cada vuelo de caza; Postura muy vertical, con las alas caídas; Frente y pecho con un rayado fino y difuso', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/SpottedFlycatcheronfence.jpg?width=1280', 'Andrew Easton (Attribution) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 2 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población reproductora, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Muscicapa', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12250, 2492576, 'ES0000261', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Chotacabras cuellirrojo', 'Caprimulgus ruficollis', 'fauna', 'Ave', 'Matorral abierto, pinares aclarados, ramblas y caminos térreos', 'Protegida (LESRPE)', 'Ave crepuscular de plumaje jaspeado que imita la hojarasca, tan mimético que de día resulta casi imposible verla posada en el suelo. Caza polillas en vuelo con la boca muy abierta. Su canto nocturno es un «cu-toc, cu-toc» repetido de forma monótona durante minutos.', NULL, 'Collar rojizo en la nuca, más marcado que en su pariente europeo; Se levanta del camino al anochecer y vuelve a posarse unos metros más allá; Canto nocturno monótono, como un motor lejano', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Caprimulgus_ruficollis_-Portugal-8.jpg?width=1280', 'Olivença (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 1 ocurrencia dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Caprimulgus', 'NT (Casi amenazado)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12122, 9411857, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Chorlitejo patinegro', 'Charadrius alexandrinus', 'fauna', 'Ave limícola', 'Playas, salinas, marismas y llanos arenosos junto al mar', 'Interés especial', 'Chorlitejo pequeño y pálido, de patas oscuras, que corretea por la arena en carreras cortas seguidas de paradas bruscas. Su nido es una simple depresión en la arena con los huevos perfectamente camuflados, por lo que las puestas se pierden con facilidad bajo el pisoteo.', NULL, 'Collar oscuro interrumpido en el centro del pecho; Corre a ratos y se para en seco, una y otra vez; Plumaje muy pálido, del color de la arena seca', 'Todo el año, con máximos en primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Charadrius_alexandrinus_-_Kentish_Plover_03.jpg?width=1280', 'Zeynel Cebeci (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"Catálogo Español de Especies Amenazadas (CEEA): Vulnerable","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 1, 1, NULL, 'GBIF confirma su presencia con 1 ocurrencia dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Charadriiformes', 'Charadriidae', 'Charadrius', 'LC', 'Catálogo Español de Especies Amenazadas (CEEA): Vulnerable; LESRPE (RD 139/2011); Ley 42/2007, Anexo IV', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 10664, 2480311, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Gaviota reidora', 'Chroicocephalus ridibundus', 'fauna', 'Ave marina', 'Costas, salinas, embalses, ríos y campos de cultivo inundados', 'LC', 'Gaviota pequeña y ágil, muy común en invierno tierra adentro. En verano lleva la cabeza cubierta por una capucha de color chocolate; en invierno solo le queda una mancha oscura tras el ojo. En vuelo enseña una cuña blanca inconfundible en el borde delantero del ala.', NULL, 'Cuña blanca en el filo delantero del ala, visible en vuelo; En invierno, una mancha oscura como un auricular tras el ojo; Pico y patas rojo oscuro', 'Otoño e invierno', 'https://inaturalist-open-data.s3.amazonaws.com/photos/605325270/original.jpg', 'lalaia (CC BY 4.0) · GBIF', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 1, NULL, 'GBIF confirma su presencia con 1 ocurrencia dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2, que la cita como «Larus ridibundus»: población invernante, presente; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', NULL, NULL, 'Chroicocephalus', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 16356, 6065824, 'ES0000261', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Culebrera europea', 'Circaetus gallicus', 'fauna', 'Ave rapaz', 'Sierras y llanos con matorral, ramblas y bosque abierto', 'Interés especial', 'Águila grande y muy pálida por debajo, especializada en comer culebras y lagartos. Se ciñe en el aire durante largos ratos, con las patas colgando, escrutando el suelo antes de dejarse caer. La cabeza, ancha y con ojos amarillos muy frontales, le da un aire de lechuza.', NULL, 'Vientre y alas casi blancos vistos desde abajo; Se mantiene cerniéndose, algo raro en un águila tan grande; Cabeza ancha y ojos amarillos, aspecto de búho', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aguila_culebrera_(Circaetus_gallicus).jpg?width=1280', 'Paco Gómez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF confirma su presencia con 1 ocurrencia dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Circaetus', 'LC (Preocupación menor)', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE; Ley 42/2007, Anexo IV', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 11336, 2480666, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Curruca tomillera', 'Curruca conspicillata', 'fauna', 'Ave', 'Matorral bajo y abierto, tomillares y saladares con arbustos dispersos', 'Protegida (LESRPE)', 'Curruca menuda de matorral raso, gris en la cabeza, parda en el dorso y con las plumas del ala ribeteadas de castaño encendido. El anillo blanco del ojo le da el aire de «gafas» que le da nombre. Es inquieta y suele delatarse por su reclamo antes de dejarse ver.', NULL, 'Anillo blanco alrededor del ojo bien marcado; Panel castaño vivo en el ala plegada; Vive en matorral muy bajo, no en arbolado', 'Todo el año en el sureste; parcialmente migradora', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fauvette_%C3%A0_lunettes_Aqueduc_de_Zaghouan.jpg?width=1280', 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 1 ocurrencia dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2, que la cita como «Sylvia conspicillata»: población reproductora, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'LC (Preocupación menor)', 'Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 80923, 9868071, 'ES0000261', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Azor común', 'Accipiter gentilis', 'fauna', 'Ave rapaz', 'Bosques maduros y masas forestales densas con claros', 'Protegida (LESRPE)', 'Rapaz forestal de alas cortas y anchas y cola larga, diseñada para perseguir presas entre los árboles a gran velocidad. Es esquiva y se ve casi siempre de refilón. La hembra llega a ser un tercio mayor que el macho, una diferencia poco habitual entre las aves.', NULL, 'Ceja blanca marcada sobre el ojo, como un antifaz al revés; Vuelo de varios aleteos rápidos seguidos de un planeo corto; Pecho finamente rayado en horizontal en los adultos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Northern_Goshawk_ad_M2.jpg?width=1280', 'Norbert Kenntner, Berlin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF confirma su presencia con 0 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Accipiter', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11351, 2480589, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
