-- ------------------------------------------------------------------------------------------------
-- 5. Comprobación posterior. Debe devolver exactamente los recuentos de la cabecera.
-- ------------------------------------------------------------------------------------------------
SELECT
    (SELECT COUNT(*) FROM parks WHERE slug = 'sierra-de-las-moreras') AS espacio,
    (SELECT COUNT(*) FROM habitats h JOIN parks p ON p.id = h.park_id WHERE p.slug = 'sierra-de-las-moreras') AS habitats,
    (SELECT COUNT(*) FROM species s JOIN parks p ON p.id = s.park_id WHERE p.slug = 'sierra-de-las-moreras') AS especies,
    (SELECT COUNT(*) FROM species_habitats sh JOIN species s ON s.id = sh.species_id JOIN parks p ON p.id = s.park_id WHERE p.slug = 'sierra-de-las-moreras') AS vinculos;
